+}
+
+func TestToSnakeCase(t *testing.T) {
+	tests := []struct {
+		input string
+		want  string
+	}{
+		{
+			input: "DatabaseGroup",
+			want:  "database_group",
+		},
+		{
+			input: "User",
+			want:  "user",
+		},
+		{
+			input: "Instance",
+			want:  "instance",
+		},
+		{
+			input: "IdentityProvider",
+			want:  "identity_provider",
+		},
+	}
+
+	for _, tt := range tests {
+		got := toSnakeCase(tt.input)
+		require.Equal(t, tt.want, got, tt.input)
+	}
+}

