+	case *v1pb.AddDataSourceRequest:
+		return r.GetName()
+	case *v1pb.RemoveDataSourceRequest:
+		return r.GetName()
+	case *v1pb.UpdateDataSourceRequest:
+		return r.GetName()
+	case *v1pb.UpdateSettingRequest:
