+func convertToAuditLogs(ctx context.Context, stores *store.Store, auditLogs []*store.AuditLog) ([]*v1pb.AuditLog, error) {
+	var ls []*v1pb.AuditLog
+	for _, log := range auditLogs {
+		l, err := convertToAuditLog(ctx, stores, log)
+		if err != nil {
+			return nil, err
+		}
+		ls = append(ls, l)
+	}
+	return ls, nil
