+
+func TestGetFirstSemanticTypeInPath(t *testing.T) {
+	containerName := "container"
+	containerNode := base.NewItemSelector(containerName)
+
+	testCases := []struct {
+		nodes        []base.SelectorNode
+		objectSchema *storepb.ObjectSchema
+		want         string
