+		require.NoError(t, err, tc.description)
+
+		output, err := json.Marshal(got)
+		require.NoError(t, err, tc.description)
+
+		require.NoError(t, err, tc.description)
+		require.JSONEqf(t, tc.want, string(output), tc.description)
+	}
+}

