+	}
+	if user == nil {
+		return nil, errors.Errorf("user %q not found", v.User)
+	}
+	return &storepb.GrantRequest{
+		Role:       v.Role,
+		User:       common.FormatUserUID(user.ID),
+		Condition:  v.Condition,
+		Expiration: v.Expiration,
+	}, nil
+}
